// messages.publish-history.list: a window of what the caller published on one connection (PUB-02)
// Generated by `pnpm nx g @app/generators:action messages.publish-history.list`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  HistorySummarySchema,
  PUBLISH_HISTORY_LIMITS,
  PUBLISH_LIMITS,
} from './publish-types.ts';
import { VhostNameSchema } from './topology-types.ts';

export const MessagesPublishHistoryListInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  vhost: VhostNameSchema.optional(),
  /** Exact; an empty value is the default exchange. */
  exchange: z.string().max(PUBLISH_LIMITS.textMax).optional(),
  /** Exact, case-sensitive prefix of the routing key. */
  routingKeyPrefix: z.string().max(PUBLISH_LIMITS.textMax).optional(),
  /** At or after / at or before this time (epoch ms). */
  from: z.number().int().nonnegative().optional(),
  to: z.number().int().nonnegative().optional(),
  /** 1 to 200; 50 when absent. */
  limit: z
    .number()
    .int()
    .min(1)
    .max(PUBLISH_HISTORY_LIMITS.windowMax)
    .optional(),
  /** The `nextCursor` of the previous window. */
  cursor: z.string().min(1).max(PUBLISH_HISTORY_LIMITS.cursorMax).optional(),
});

export const MessagesPublishHistoryListOutputSchema = z.strictObject({
  /** Newest first (I-7: a keyset window, never the whole history). */
  entries: z.array(HistorySummarySchema).max(PUBLISH_HISTORY_LIMITS.windowMax),
  nextCursor: z
    .string()
    .min(1)
    .max(PUBLISH_HISTORY_LIMITS.cursorMax)
    .optional(),
});

export const messagesPublishHistoryList = defineAction({
  id: 'messages.publish-history.list',
  kind: 'query',
  summary: 'List what the caller published on a connection, newest first',
  input: MessagesPublishHistoryListInputSchema,
  output: MessagesPublishHistoryListOutputSchema,
  // History is per owner, so only a publisher has any; no separate history permission exists.
  permission: 'messages.publish',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({ connectionId: input.cid }),
  http: { method: 'GET', path: '/connections/{cid}/messages/publish-history' },
  cli: { command: 'messages publish-history list' },
  since: '1.0',
});
